negativeExample:
package test;

import org.eclipse.jface.viewers.ArrayContentProvider;
import org.eclipse.jface.viewers.TableViewer;
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Shell;

public class MyOtherClass {
    public void setupViewer(Shell parent) {
        TableViewer fViewer = new TableViewer(parent, SWT.MULTI);
        fViewer.setContentProvider(ArrayContentProvider.getInstance()); // Already uses getInstance()
        fViewer.setContentProvider(new MyCustomContentProvider()); // Different class, should not match
    }
    private static class MyCustomContentProvider extends ArrayContentProvider {}
}
